import React, { useEffect } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import { fetchEvents } from '../../../../features/eventOwner/eventOwnerSlice'; // Adjust path as necessary
import CreateEventForm from '../CreateEventForm'; // Adjust path as necessary
import EventList from '../EventList'; // Adjust path as necessary
import TicketManagement from '../TicketManagement'; // Adjust path as necessary
import ViewBookings from '../ViewBookings'; // Adjust path as necessary
import ViewFeedbacks from '../ViewFeedbacks'; // Adjust path as necessary
import './EventOwnerDashboard.css'; // Import your CSS for styling

const EventOwnerDashboard = () => {
  const dispatch = useDispatch();
  
  // Access event state from Redux store
  const { events, loading, error } = useSelector((state) => state.eventOwner);

  useEffect(() => {
    // Fetch events when the component mounts
    dispatch(fetchEvents());
  }, [dispatch]);

  return (
    <div className="event-owner-dashboard-container">
      <h2>Event Owner Dashboard</h2>

      {loading && <p>Loading...</p>}
      {error && <p className="error-message">{error}</p>}

      <CreateEventForm /> {/* Component for creating events */}
      <EventList events={events} /> {/* Component to list events */}
      <TicketManagement /> {/* Component for managing ticket availability */}
      <ViewBookings /> {/* Component to view user bookings */}
      <ViewFeedbacks /> {/* Component to view feedback from users */}
    </div>
  );
};

export default EventOwnerDashboard;




